/// Parse TOML text into a deterministic JSON value.
/// Raises on malformed input.
pub fn parse_toml(text : String) -> Json raise ParseError {
  let lines = text.split("\n")
  let mut table_path : Array[String] = []
  // Collect entries: (path_prefix, key, value)
  let mut entries : Array[(Array[String], String, Json)] = []
  for i in 0..<lines.length() {
    let line = lines[i]
    let trimmed = line.trim()
    // Skip blank lines and comments
    if trimmed.is_empty() || trimmed[0] is '#' {
      continue
    }
    // Check for table header
    if trimmed[0] is '[' {
      let close = trimmed.index_of(']', 1)
      if close < 0 {
        raise ParseError::Syntax("line \{i + 1}: unclosed table header")
      }
      let inner = trimmed.sub(start=1, end=close).trim()
      if inner.is_empty() {
        raise ParseError::Syntax("line \{i + 1}: empty table header")
      }
      table_path = inner.split(".").map(fn(s) { s.trim() }).to_array()
      // Validate table path parts
      for part in table_path {
        if part.is_empty() || !is_valid_bare_key(part) {
          raise ParseError::Syntax(
            "line \{i + 1}: invalid table key: \"\{part}\"",
          )
        }
      }
      // Check for trailing content after ]
      let after = trimmed.sub(start=close + 1).trim()
      if !after.is_empty() && after[0] isnt '#' {
        raise ParseError::Syntax(
          "line \{i + 1}: trailing content after table header",
        )
      }
      continue
    }
    // Parse key-value pair
    let eq_pos = index_of_eq(trimmed)
    if eq_pos < 0 {
      raise ParseError::Syntax(
        "line \{i + 1}: expected key = value, no '=' found",
      )
    }
    let raw_key = trimmed.sub(start=0, end=eq_pos).trim()
    let raw_value = trimmed.sub(start=eq_pos + 1).trim()
    if raw_key.is_empty() {
      raise ParseError::Syntax("line \{i + 1}: missing key before '='")
    }
    // Parse key (possibly dotted)
    let key_parts = raw_key.split(".").map(fn(s) { s.trim() }).to_array()
    for part in key_parts {
      if part.is_empty() || !is_valid_bare_key(part) {
        raise ParseError::Syntax(
          "line \{i + 1}: invalid key: \"\{part}\"",
        )
      }
    }
    // The last part is the actual key; the rest are sub-table path
    let actual_key = key_parts[key_parts.length() - 1]
    let sub_path = key_parts[0:key_parts.length() - 1].to_array()
    let full_path = table_path + sub_path
    let value = parse_value(raw_value, i + 1)
    entries.push((full_path, actual_key, value))
  }
  // Build JSON object from entries, checking for duplicates
  build_json(entries)
}

///|
/// Check for duplicate keys in the assembled JSON object.
fn check_duplicates(obj : Map[String, Json], key : String, line : Int) -> Unit raise ParseError {
  if obj.contains(key) {
    raise ParseError::DuplicateKey(
      "duplicate key \"\{key}\" at line \{line}",
    )
  }
}

///|
fn build_json(entries : Array[(Array[String], String, Json)]) -> Json raise ParseError {
  let mut root : Map[String, Json] = Map::new()
  for i in 0..<entries.length() {
    let (path, key, value) = entries[i]
    if path.is_empty() {
      check_duplicates(root, key, -1)
      root[key] = value
    } else {
      // Navigate to the nested table
      let mut current = root
      for j in 0..<path.length() {
        let part = path[j]
        if j == path.length() - 1 {
          // Last part: ensure it's an object, then insert
          if current.contains(part) {
            match current[part] {
              Json::Object(sub) => {
                check_duplicates(sub, key, -1)
                sub[key] = value
              }
              _ => {
                raise ParseError::InvalidType(
                  "cannot set key \"\{key}\" on non-table value at \"\{part}\"",
                )
              }
            }
          } else {
            let new_obj : Map[String, Json] = Map::new()
            new_obj[key] = value
            current[part] = Json::object(new_obj)
          }
        } else {
          // Intermediate part: ensure it's an object
          if current.contains(part) {
            match current[part] {
              Json::Object(sub) => current = sub
              _ => {
                raise ParseError::InvalidType(
                  "cannot navigate into non-table value at \"\{part}\"",
                )
              }
            }
          } else {
            let new_obj : Map[String, Json] = Map::new()
            current[part] = Json::object(new_obj)
            match current[part] {
              Json::Object(sub) => current = sub
              _ => ()
            }
          }
        }
      }
    }
  }
  Json::object(root)
}

///|
fn parse_value(text : StringView, line : Int) -> Json raise ParseError {
  let s = text.to_owned()
  if s.is_empty() {
    raise ParseError::Syntax("line \{line}: missing value")
  }
  // String
  if s[0] is '"' {
    let (value, _) = parse_string(s, 0, line)
    return Json::string(value)
  }
  // Boolean
  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }
  // Array
  if s[0] is '[' {
    return parse_array(s, line)
  }
  // Integer (optional sign followed by digits)
  let mut start = 0
  if s[0] is '+' | '-' {
    start = 1
  }
  if start < s.length() {
    let mut all_digits = true
    for j in start..<s.length() {
      if s[j] < '0' || s[j] > '9' {
        all_digits = false
        break
      }
    }
    if all_digits && start < s.length() {
      let n : Int = @string.parse_int(s) catch {
        _ => raise ParseError::Syntax("line \{line}: invalid integer: \"\{s}\"")
      }
      return Json::number(n.to_double(), repr=s)
    }
  }
  raise ParseError::Syntax("line \{line}: unrecognized value: \"\{s}\"")
}

///|
fn parse_string(s : String, start : Int, line : Int) -> (String, Int) raise ParseError {
  guard s[start] is '"' else {
    raise ParseError::Syntax("line \{line}: expected opening quote")
  }
  let mut i = start + 1
  let mut result = StringBuilder::new()
  while i < s.length() {
    let c = s[i]
    if c is '"' {
      return (result.to_string(), i + 1)
    } else if c is '\\' {
      i += 1
      if i >= s.length() {
        raise ParseError::Syntax("line \{line}: unclosed string escape")
      }
      match s[i] {
        '"' => result.write_char('"')
        '\\' => result.write_char('\\')
        'n' => result.write_char('\n')
        't' => result.write_char('\t')
        _ => raise ParseError::Syntax(
          "line \{line}: invalid escape: \\\{s[i]}",
        )
      }
      i += 1
    } else if c is '\n' {
      raise ParseError::Syntax("line \{line}: newline in string")
    } else {
      result.write_char(c)
      i += 1
    }
  }
  raise ParseError::Syntax("line \{line}: unclosed string")
}

///|
fn parse_array(s : String, line : Int) -> Json raise ParseError {
  guard s[0] is '[' else {
    raise ParseError::Syntax("line \{line}: expected '['")
  }
  guard s[s.length() - 1] is ']' else {
    raise ParseError::Syntax("line \{line}: unclosed array")
  }
  let inner = s.sub(start=1, end=s.length() - 1).trim()
  if inner.is_empty() {
    return Json::array([])
  }
  let mut items : Array[Json] = []
  // Parse comma-separated values
  let mut i = 0
  while i < inner.length() {
    // Skip whitespace
    while i < inner.length() && inner[i] is ' ' {
      i += 1
    }
    if i >= inner.length() {
      break
    }
    let start = i
    // Determine value type and parse accordingly
    if inner[i] is '"' {
      // String value
      let (value, end) = parse_string(inner, i, line)
      items.push(Json::string(value))
      i = end
    } else if inner[i] is '[' {
      // Nested array - find matching ]
      let mut depth = 1
      let mut j = i + 1
      while j < inner.length() && depth > 0 {
        if inner[j] is '[' {
          depth += 1
        } else if inner[j] is ']' {
          depth -= 1
        }
        j += 1
      }
      let arr_text = inner.sub(start=i, end=j).to_owned()
      items.push(parse_array(arr_text, line))
      i = j
    } else {
      // Boolean or integer
      while i < inner.length() && inner[i] isnt ',' && inner[i] isnt ' ' && inner[i] isnt ']' {
        i += 1
      }
      let val_text = inner.sub(start=start, end=i).trim().to_owned()
      if val_text.is_empty() {
        raise ParseError::Syntax("line \{line}: empty array element")
      }
      let val = parse_value(val_text, line)
      items.push(val)
    }
    // Skip whitespace and comma
    while i < inner.length() && inner[i] is ' ' {
      i += 1
    }
    if i < inner.length() && inner[i] is ',' {
      i += 1
    }
  }
  Json::array(items)
}

///|
/// Find the first `=` that is not inside a string or array.
fn index_of_eq(s : StringView) -> Int {
  let mut depth = 0
  let mut in_string = false
  let mut i = 0
  while i < s.length() {
    let c = s[i]
    if in_string {
      if c is '\\' {
        i += 2
        continue
      }
      if c is '"' {
        in_string = false
      }
      i += 1
      continue
    }
    if c is '"' {
      in_string = true
      i += 1
      continue
    }
    if c is '[' {
      depth += 1
    } else if c is ']' {
      depth -= 1
    } else if c is '=' && depth == 0 {
      return i
    }
    i += 1
  }
  -1
}

///|
/// Validate a bare key: alphanumeric, underscore, dash allowed.
fn is_valid_bare_key(s : StringView) -> Bool {
  if s.length() == 0 {
    return false
  }
  for i in 0..<s.length() {
    let c = s[i]
    if !(c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' &&
      c <= '9' || c is '_' || c is '-')
    {
      return false
    }
  }
  true
}
