          match current[part] {
            Json::Object(sub) => current = sub
            _ => ()
          }
        }
      }
    }
  }
  Json::object(root)
}

///|
fn parse_value(text : StringView, line : Int) -> Json raise ParseError {
  let s = text.to_owned()
  if s.is_empty() {
    raise ParseError::Syntax("line \{line}: missing value")
  }
  // String
  if s[0] is '"' {
    let (value, _) = parse_string(s, 0, line)
    return Json::string(value)
  }
  // Boolean
  if s == "true" {
    return Json::boolean(true)
  }
  if s == "false" {
    return Json::boolean(false)
  }
  // Array
  if s[0] is '[' {
    return parse_array(s, line)
  }
