  guard s[start] is '"' else {
    raise ParseError::Syntax("line \{line}: expected opening quote")
  }
  let mut i = start + 1
  let mut result = StringBuilder::new()
  while i < s.length() {
    let c = s[i]
    if c is '"' {
      return (result.to_string(), i + 1)
    } else if c is '\\' {
      i += 1
