///|
test "basic key-value" {
  let result = parse_toml(#|key = "value"
number = 42
boolean = true)
  inspect(result.stringify(), content="{\"boolean\":true,\"key\":\"value\",\"number\":42}")
}

///|
test "table" {
  let result = parse_toml(#|[owner]
name = "Alice"
age = 30)
  inspect(result.stringify(), content="{\"owner\":{\"age\":30,\"name\":\"Alice\"}}")
}

///|
test "nested table" {
  let result = parse_toml(#|[database.settings]
host = "localhost"
port = 5432)
  inspect(
    result.stringify(),
    content="{\"database\":{\"settings\":{\"host\":\"localhost\",\"port\":5432}}}",
  )
}

///|
test "dotted keys" {
  let result = parse_toml(#|a.b.c = "deep"
x.y = true)
  inspect(result.stringify(), content="{\"a\":{\"b\":{\"c\":\"deep\"}},\"x\":{\"y\":true}}")
}

///|
test "array" {
  let result = parse_toml(#|arr = [1, 2, 3]
bools = [true, false])
  inspect(result.stringify(), content="{\"arr\":[1,2,3],\"bools\":[true,false]}")
}

///|
test "string escapes" {
  let result = parse_toml(#|escaped = "hello\nworld\t\"quoted\"\\")
  inspect(
    result.stringify(),
    content="{\"escaped\":\"hello\\nworld\\t\\\"quoted\\\"\\\\\"}",
  )
}

///|
test "comments and blank lines" {
  let result = parse_toml(#|# comment
key = "v"
# another

other = 99)
  inspect(result.stringify(), content="{\"key\":\"v\",\"other\":99}")
}

///|
test "duplicate key error" {
  let result = try parse_toml(#|key = "first"
key = "second")
  catch {
    ParseError::DuplicateKey(msg) => Some(msg)
    _ => None
  } noraise {
    _ => fail("expected DuplicateKey error")
  }
  match result {
    Some(msg) => assert_true(msg.contains("duplicate key"))
    _ => fail("expected error")
  }
}

