  catch {
    ParseError::Syntax(msg) => Some(msg)
    _ => None
  } noraise {
    _ => fail("expected Syntax error")
  }
  match result {
    Some(msg) => assert_true(msg.length() > 0)
    _ => fail("expected error")
  }
